"""Triton implementation of aten::_compute_linear_combination.

Semantics (ATen):
    coefficients: (M, N)
    input:        (N, s1, ..., sd)
    output:       (M, s1, ..., sd) with
        out[i, r] = sum_k coefficients[i, k] * input[k, r]
    where r indexes the flattened trailing dimensions of ``input``.

The kernel is a strided matrix-matrix product: one program computes a
(BLOCK_M, BLOCK_R) output tile with a BLOCK_K tiled ``tl.dot`` accumulation.
fp32 uses ``input_precision="ieee"`` (no tf32) to stay inside the pytest fp32
tolerance; fp16/bf16 accumulate in fp32.  Arbitrary (non-contiguous) input
strides are supported by decomposing the trailing layout into at most four
contiguous groups of (size, stride).

Memory-access specialisation: when the tile divisions are exact (EVEN_M /
EVEN_R / EVEN_K) the tile loads and the store are issued without masks, and
when the coefficient / input minor axes are unit-stride (C_UNIT / X_UNIT) the
runtime stride multiply is dropped, which lets the backend emit vectorised
accesses instead of per-element predicated dword loads.  The fully masked,
general-stride path remains for every other shape.
"""

import torch
import triton
import triton.language as tl

_MAX_GROUPS = 4
_SMEM_BUDGET = 48 * 1024


@triton.jit
def _linear_combination_kernel(
    X,  # input    (N, R) view, strides (stride_xk, trailing groups)
    C,  # coeffs   (M, N), strides (stride_cm, stride_ck)
    output_tensor,  # output   (M, R) contiguous
    M,
    N,
    R,
    stride_xk,
    stride_cm,
    stride_ck,
    s0,
    t0,
    s1,
    t1,
    s2,
    t2,
    s3,
    t3,
    BLOCK_M: tl.constexpr,
    BLOCK_R: tl.constexpr,
    BLOCK_K: tl.constexpr,
    NG: tl.constexpr,
    PREC: tl.constexpr,
    EVEN_M: tl.constexpr,
    EVEN_R: tl.constexpr,
    EVEN_K: tl.constexpr,
    X_UNIT: tl.constexpr,
    C_UNIT: tl.constexpr,
):
    pid_m = tl.program_id(0)
    pid_r = tl.program_id(1)

    offs_m = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    offs_r = tl.max_contiguous(pid_r * BLOCK_R + tl.arange(0, BLOCK_R), BLOCK_R)
    mask_m = offs_m < M
    mask_r = offs_r < R

    # Column offset inside the flattened trailing dimensions of ``input``.
    # Groups are innermost first; group g covers (size s_g, stride t_g) and
    # contributes ((r // P_g) % s_g) * t_g with P_g = prod_{i<g} s_i.
    if X_UNIT and NG == 1:
        xcol = offs_r
    elif NG == 1:
        xcol = offs_r * t0
    elif NG == 2:
        xcol = (offs_r % s0) * t0 + (offs_r // s0) * t1
    elif NG == 3:
        p1 = s0 * s1
        xcol = (offs_r % s0) * t0 + ((offs_r // s0) % s1) * t1 + (offs_r // p1) * t2
    else:
        p1 = s0 * s1
        p2 = p1 * s2
        xcol = (
            (offs_r % s0) * t0
            + ((offs_r // s0) % s1) * t1
            + ((offs_r // p1) % s2) * t2
            + (offs_r // p2) * t3
        )

    acc = tl.zeros((BLOCK_M, BLOCK_R), dtype=tl.float32)

    am = mask_m[:, None]
    rm = mask_r[None, :]
    k_arange = tl.arange(0, BLOCK_K)
    c_base = C + offs_m[:, None] * stride_cm
    x_base = X + xcol[None, :]
    if C_UNIT:
        a_ptrs = c_base + k_arange[None, :]
        a_step = BLOCK_K
    else:
        a_ptrs = c_base + k_arange[None, :] * stride_ck
        a_step = BLOCK_K * stride_ck
    b_ptrs = x_base + k_arange[:, None] * stride_xk
    b_step = BLOCK_K * stride_xk

    n_full = (N // BLOCK_K) * BLOCK_K
    for _ in tl.range(0, n_full, BLOCK_K):
        if EVEN_M:
            if EVEN_R:
                a = tl.load(a_ptrs)
                b = tl.load(b_ptrs)
            else:
                a = tl.load(a_ptrs)
                b = tl.load(b_ptrs, mask=rm, other=0.0)
        else:
            if EVEN_R:
                a = tl.load(a_ptrs, mask=am, other=0.0)
                b = tl.load(b_ptrs)
            else:
                a = tl.load(a_ptrs, mask=am, other=0.0)
                b = tl.load(b_ptrs, mask=rm, other=0.0)
        acc = tl.dot(a, b, acc, input_precision=PREC)
        a_ptrs += a_step
        b_ptrs += b_step

    if not EVEN_K:
        # Tail tile: only this one needs the contraction-axis mask.
        k_mask = n_full + k_arange < N
        a = tl.load(a_ptrs, mask=am & k_mask[None, :], other=0.0)
        b = tl.load(b_ptrs, mask=k_mask[:, None] & rm, other=0.0)
        acc = tl.dot(a, b, acc, input_precision=PREC)

    o_ptrs = output_tensor + offs_m[:, None] * R + offs_r[None, :]
    if EVEN_M and EVEN_R:
        tl.store(o_ptrs, acc.to(output_tensor.dtype.element_ty))
    else:
        tl.store(o_ptrs, acc.to(output_tensor.dtype.element_ty), mask=am & rm)


def _collapse_trailing(shape, strides):
    """Collapse trailing dims (1..len-1) into <=4 contiguous (size, stride) groups.

    Groups are ordered innermost first.
    """
    groups = []
    cur_size = 1
    cur_stride = 0
    have = False
    for i in range(len(shape) - 1, 0, -1):
        s = shape[i]
        if s == 1:
            continue
        st = strides[i]
        if not have:
            cur_size = s
            cur_stride = st
            have = True
        elif st == cur_size * cur_stride:
            cur_size *= s
        else:
            groups.append((cur_size, cur_stride))
            cur_size = s
            cur_stride = st
    if have:
        groups.append((cur_size, cur_stride))
    else:
        groups.append((1, 0))
    return groups


def _next_pow2(v):
    p = 1
    while p < v:
        p *= 2
    return p


def _pick_blocks(m, r, n, elem_size):
    """Pick (BLOCK_M, BLOCK_R, BLOCK_K, num_warps, num_stages).

    Target: enough programs to fill the 16 SMs at least twice while keeping the
    per-program tile large enough to amortise addressing.
    """
    bk = 16
    while bk < n and bk < 32:
        bk *= 2

    bms = [b for b in (64, 32, 16) if b <= max(16, _next_pow2(m))]
    brs = [b for b in (128, 64, 32, 16) if b <= max(16, _next_pow2(r))]

    cands = []
    for bm in bms:
        gm = (m + bm - 1) // bm
        for br in brs:
            area = bm * br
            if area > 4096:
                continue
            blocks = gm * ((r + br - 1) // br)
            cands.append((blocks, area, bm, br))

    choice = None
    for threshold in (32, 16, 1):
        pool = [c for c in cands if c[0] >= threshold]
        if pool:
            # largest tile first, then the largest M tile (less coefficient reuse cost)
            choice = pool[0]
            for c in pool[1:]:
                if (c[1], c[2]) > (choice[1], choice[2]):
                    choice = c
            break
    _, area, bm, br = choice

    nw = max(1, min(8, area // 256))
    per_stage = (bm * bk + bk * br) * elem_size
    ns = 3
    while ns > 1 and per_stage * ns > _SMEM_BUDGET:
        ns -= 1
    return bm, br, bk, nw, ns


def _compute_linear_combination(input, coefficients, out=None):
    if input.dim() == 0:
        raise RuntimeError(
            "_compute_linear_combination: input must have at least 1 dimension"
        )
    if coefficients.dim() != 2:
        raise RuntimeError(
            "_compute_linear_combination: coefficients must be 2-dimensional"
        )

    m = coefficients.shape[0]
    n = coefficients.shape[1]
    in_shape = input.shape
    if in_shape[0] != n:
        raise RuntimeError(
            "_compute_linear_combination: input and coefficients must have the "
            "same number of columns"
        )
    if input.numel() == 0:
        raise RuntimeError(
            "_compute_linear_combination: empty input tensor not supported"
        )

    out_shape = (m,) + tuple(in_shape[1:])
    r = 1
    for d in in_shape[1:]:
        r *= d

    if out is None:
        out = torch.empty(out_shape, dtype=input.dtype, device=input.device)
    elif tuple(out.shape) != out_shape:
        raise RuntimeError("_compute_linear_combination: incompatible output shape")

    if m == 0:
        return out

    groups = _collapse_trailing(in_shape, input.stride())
    if len(groups) > _MAX_GROUPS:
        raise RuntimeError(
            "_compute_linear_combination: unsupported input layout "
            "(too many non-contiguous stride groups)"
        )

    g0 = groups[0]
    g1 = groups[1] if len(groups) > 1 else (1, 1)
    g2 = groups[2] if len(groups) > 2 else (1, 1)
    g3 = groups[3] if len(groups) > 3 else (1, 1)

    stride_ck = coefficients.stride(1)
    bm, br, bk, nw, ns = _pick_blocks(m, r, n, input.element_size())

    _linear_combination_kernel[(triton.cdiv(m, bm), triton.cdiv(r, br))](
        input,
        coefficients,
        out,
        m,
        n,
        r,
        input.stride(0),
        coefficients.stride(0),
        stride_ck,
        g0[0],
        g0[1],
        g1[0],
        g1[1],
        g2[0],
        g2[1],
        g3[0],
        g3[1],
        BLOCK_M=bm,
        BLOCK_R=br,
        BLOCK_K=bk,
        NG=len(groups),
        PREC="ieee",
        EVEN_M=(m % bm == 0),
        EVEN_R=(r % br == 0),
        EVEN_K=(n % bk == 0),
        X_UNIT=(len(groups) == 1 and g0[1] == 1),
        C_UNIT=(stride_ck == 1),
        num_warps=nw,
        num_stages=ns,
    )
    return out
